# v681 Khezaroth, Medusara, Vaelthar and the Omega Cube move sets; the Advisor's lines in boss fights (see p681_boss.js)
import sys
p = sys.argv[1]; s = open(p, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a)
    if c != n: raise SystemExit(f'expected {n} got {c}: {a[:100]}')
    s = s.replace(a, b)
R = lambda f: open('tools/patches/' + f, encoding='utf-8').read()
rep('function spawnVolley(b, v) { fx589Spawn(b, v);', R('p681_boss.js') + 'function spawnVolley(b, v) { fx589Spawn(b, v);')
