rep('if (!m.snd) { m.snd = 1; aexSfx(m.a); }', 'if (!m.snd) { m.snd = 1; aexSfx(m.a); if (m.a === "frac") bVoice(b, "sig"); }')
rep('if (!m.snd && u >= 0) { m.snd = 1; mimSfx(', 'if (!m.snd && u >= 0 && (m.a === "omegaX" || m.a === "storm")) bVoice(b, "sig"); /* v681 */ if (!m.snd && u >= 0) { m.snd = 1; mimSfx(')
rep('if (b.intro <= 0) while (b.vi < b.R.vols.length && cineDue(b, b.R.vols[b.vi], T)) spawnVolley(b, b.R.vols[b.vi++]);', 'if (b.intro <= 0 && !b.bv_open && T > .15) bVoice(b, "open"); /* v681 the Advisor opens every boss fight */ if (b.intro <= 0) while (b.vi < b.R.vols.length && cineDue(b, b.R.vols[b.vi], T)) spawnVolley(b, b.R.vols[b.vi++]);')
rep('  for (const m of b.aexA || []) { const u = (T - m.t0) / AEX_DUR[m.a]; if (u > -.4', '  for (const m of b.bmA || []) { const u = (T - m.t0) / BMV_DUR[m.a]; if (u > -.4 && u < .4) { b.focus = { s: 1, x: .5, y: .5, until: t + (m.sig ? 4200 : 2600), cine: "boss" }; C.n++; return; } } /* v681 */\n  for (const m of b.aexA || []) { const u = (T - m.t0) / AEX_DUR[m.a]; if (u > -.4')
rep('function wbStrike(ctx, b, scr, Q, W, H, t, d, lo) { const k = b.r && b.r.wb, M = WBR.mv;', 'function wbStrike(ctx, b, scr, Q, W, H, t, d, lo) { const k = b.r && (b.r.wb || (b.r.sbk && WB_STRIKE[b.r.sbk] ? b.r.sbk : null)) /* v681 super bosses too */, M = WBR.mv;')
rep(': [WB[k].col], col = j => els[j % els.length];', ': [(WB[k] || SBW[k]).col], col = j => els[j % els.length];')
rep('if (!c.fired && e >= T2) { c.fired = 1; const m = wbMoves(key), mv = m[(Math.random() * m.length) | 0]; WBR.b.act(mv); WBR.mv = { m: mv, t0: t }; if (battle && WBR.awe !== battle) { WBR.awe = battle; if (!G.stress || !G.stress.busy) aweSay(key, .55); } }', 'if (!c.fired && e >= T2) { c.fired = 1; if (!(battle && battle.r && battle.r.sbk === key && BMV_ACT[key])) /* v681 in these fights the battle chooses the move */ { const m = wbMoves(key), mv = m[(Math.random() * m.length) | 0]; WBR.b.act(mv); WBR.mv = { m: mv, t0: t }; if (battle && WBR.awe !== battle) { WBR.awe = battle; if (!G.stress || !G.stress.busy) aweSay(key, .55); } } }')
rep('const AEX_DUR = { sweep: 1.6, lance: 1.25, frac: 2.9 };', 'const AEX_DUR = { sweep: 1.6, lance: 1.25, frac: 2.9, missiles: 1.5, broadside: 1.1 };')
rep('let a = A.length % 2 ? "sweep" : "lance";', 'let a = ["lance", "missiles", "sweep", "broadside"][A.length % 4]; /* v681 */')
